const planes = [];
for (let k = 0; k < 10; k++) {
  const u = rand(seed, k, 1) * 1.6 - 0.6, a = rand(seed, k, 2) * 6.2832, s = Math.sqrt(1 - u * u);
  planes.push([set(s * Math.cos(a), u, s * Math.sin(a)), 0.27 + 0.12 * rand(seed, k, 3)]);
}
const n = npoints(0);
for (let i = 0; i < n; i++) {
  let p = point(0, 'P', i);
  for (const [nrm, d] of planes) { const h = dot(p, nrm); if (h > d) p = sub(p, mul(nrm, h - d)); }
  setpointattrib(0, 'P', i, set(p.x * 1.35, p.y * 0.85, p.z * 1.1));
}

const y0 = 0.45, y1 = 1.9;
if (@P.y > y0 && @P.y < y1) {
  const a = Math.atan2(@P.z, @P.x), r = Math.hypot(@P.x, @P.z);
  const t = (@P.y - y0) / (y1 - y0);
  const ends = Math.min(1, t / 0.04, (1 - t) / 0.04);
  let k = 1 - 0.2 * ends * Math.pow(0.5 + 0.5 * Math.cos(8 * a), 2);
  const a0 = rand(seed) * 6.2832 + 0.5 * Math.sin(t * 7 + seed) + 0.12 * Math.sin(t * 31 + 2 * seed);
  let da = a - a0; da -= 6.2832 * Math.round(da / 6.2832);
  const d = Math.abs(da) * r, w = 0.02 + 0.06 * Math.sin(3.1416 * t);
  if (d < w) k -= 0.35 * (1 - d / w);
  @P.x *= k; @P.z *= k;
}

const n = npoints(0);
let lo = 1e9, hi = -1e9;
for (let i = 0; i < n; i++) { const y = point(0, 'P', i).y; lo = min(lo, y); hi = max(hi, y); }
let c = point(0, 'P', 0);
for (let k = 0; k < 50; k++) {
  c = point(0, 'P', floor(rand(seed + 3, k) * n));
  if (c.y > lo + 0.35 * (hi - lo) && c.y < hi - 0.2 * (hi - lo)) break;
}
for (let i = 0; i < n; i++) {
  const p = point(0, 'P', i), d = distance(p, c);
  if (d < 0.12) {
    const f = 0.035 * (1 - d / 0.12);
    setpointattrib(0, 'P', i, add(p, set((rand(i, seed) - 0.5) * 2 * f, (rand(i, seed + 1) - 0.5) * 2 * f, (rand(i, seed + 2) - 0.5) * 2 * f)));
  }
}

const n = nprims(0);
